package de.ostms.lc.audit.api;
import de.ostms.lc.audit.domain.AuditEvent; import de.ostms.lc.audit.service.AuditService; import org.springframework.web.bind.annotation.*; import java.util.List;import org.springframework.http.*;
@RestController @RequestMapping("/api/audit") public class AuditController {private final AuditService service;public AuditController(AuditService s){service=s;}@GetMapping public List<AuditEvent> recent(){return service.recent();}@GetMapping(value="/export.csv",produces="text/csv")public ResponseEntity<byte[]> export(){byte[] content=service.csv();return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=Audit-Protokoll.csv").contentLength(content.length).body(content);}}
